Definition chx_side (m : mem) (it0 E lo shi n : Z) : Prop := pside m lo shi [(it0, n); (E, 24)] [(E, 24)].

Lemma chx_side_intro : forall m it0 E lo shi n,
  ACONST m -> stack0 m lo shi -> AXStatics m -> accessible m it0 n -> accessible m E 24 -> shvis m E (E + 24) ->
  aapp E 24 -> chx_side m it0 E lo shi n.
Proof.
  intros m it0 E lo shi n AC SK XS AP AE SV APE.
  pose proof (aapp_bounds E 24 APE ltac:(lia)) as (B1 & B2 & B3 & B4 & B5).
  split; [| exact XS]. split; [exact AC|]. split; [exact SK|]. split.
  - apply Forall_cons; [exact AP| apply Forall_cons; [exact AE| apply Forall_nil]].
  - apply Forall_cons; [| apply Forall_nil]. cbn [fst snd]. unfold AAPP_HI in *. split; [lia| split; [lia| split; [lia| exact SV]]].
Qed.

Lemma chx_side_elim : forall m it0 E lo shi n, chx_side m it0 E lo shi n ->
  ACONST m /\ stack0 m lo shi /\ AXStatics m /\ accessible m it0 n /\ accessible m E 24 /\ shvis m E (E + 24).
Proof.
  intros m it0 E lo shi n S. split; [exact (pside_aconst _ _ _ _ _ S)|]. split; [exact (pside_stack0 _ _ _ _ _ S)|].
  split; [exact (pside_statics _ _ _ _ _ S)|].
  split; [apply (pside_acc _ _ _ _ _ it0 n S); left; reflexivity|].
  split; [apply (pside_acc _ _ _ _ _ E 24 S); right; left; reflexivity|].
  apply (pside_shvis _ _ _ _ _ E 24 S). left. reflexivity.
Qed.

Lemma chx_pwin : forall sp it0 I E lo shi bs E0, chx_pure sp it0 I E lo shi bs E0 -> Forall pwin (chx_W lo sp I E).
Proof.
  intros sp it0 I E lo shi bs E0 (EOK & LO & CEIL & APP & QHI & ILO & IHI & IAL & APE & EAL & DQE & SPAL & SHI).
  unfold chx_W, CHX_STACK, AASSIGN_STACK, AINTRIN_STACK in *.
  repeat apply Forall_cons; [| | | | apply Forall_nil].
  - apply pwin_stack. exact CEIL.
  - apply pwin_stack. clear - CEIL LO ILO. lia.
  - eapply pwin_aapp; [exact APE| clear; lia| clear; lia].
  - exact pwin_httpcat.
Qed.

(* [comment removed for export] *)
Lemma chx_side_now : forall m m1 sp it0 I E lo shi bs E0,
  chx_side m it0 E lo shi (Z.of_nat (length bs)) -> munch (chx_W lo sp I E) m m1 -> wmono asegs m m1 ->
  chx_pure sp it0 I E lo shi bs E0 ->
  ACONST m1 /\ stack0 m1 lo shi /\ AXStatics m1 /\ accessible m1 it0 (Z.of_nat (length bs)) /\ accessible m1 E 24 /\ shvis m1 E (E + 24).
Proof.
  intros m m1 sp it0 I E lo shi bs E0 S MU WM PURE. apply chx_side_elim.
  eapply pside_transport; [exact S| exact MU| exact WM| eapply chx_pwin; exact PURE].
Qed.

(* [comment removed for export] *)
Lemma chx_cat_now : forall m m1 (sp : word) I lo g,
  AHttpCat m g -> munch [(lo, bv_unsigned sp); (I, I + 8)]%Z m m1 -> wmono asegs m m1 ->
  aceil <= lo -> bv_unsigned sp <= I -> lo <= bv_unsigned sp -> AHttpCat m1 g.
Proof.
  intros m m1 sp I lo g HC MU WM CEIL ILO LO. pose proof aceil_facts as (AF1 & _).
  eapply AHttpCat_transport; [exact HC| exact MU| exact WM| |];
    cbn [disjoint_from fst snd]; unfold AG_HTTP_CAT, AG_HTTP_CAT_GUARD; repeat split; lia.
Qed.

(* [comment removed for export] *)
Definition chx_ctx (m m1 : mem) (sp s0v s1v s2v s3v s4v rav : word) (it0 I E lo shi : Z) (bs : list byte) (itv : Z) (E0 : ecv) (g : bool)
    (j8 junk : list byte) : Prop :=
  rw_cells asegs m1 (bv_unsigned sp + -80) [CB 8 j8]
  /\ rw_cells asegs m1 (bv_unsigned sp + -72) [CB 24 junk]
  /\ rw_cells asegs m1 (bv_unsigned sp + -48) [C8 s4v; C8 s3v; C8 s2v; C8 s1v; C8 s0v; C8 rav]
  /\ rw_cells asegs m1 I [C8 (wz itv)]
  /\ rw_cells asegs m1 E (ErrCodeCells E0)
  /\ stk asegs m1 lo (bv_unsigned sp + -80)
  /\ bytes_at asegs m1 it0 bs
  /\ munch (chx_W lo sp I E) m m1 /\ wmono asegs m m1 /\ mem_inv asegs m1
  /\ munch [(lo, bv_unsigned sp); (I, I + 8)]%Z m m1
  /\ AHttpCat m g /\ chx_side m it0 E lo shi (Z.of_nat (length bs)).

(* [comment removed for export] *)
Definition chx_tctx (m m1 : mem) (sp s0v s1v s2v s3v s4v rav : word) (it0 I E lo shi : Z) (bs : list byte) (itv : Z) (E0 : ecv)
    (j8 : list byte) (e : Z) : Prop :=
  rw_cells asegs m1 (bv_unsigned sp + -80) [CB 8 j8]
  /\ rw_cells asegs m1 (bv_unsigned sp + -72) [C8 (wz e); C8 (wz AG_HTTP_CAT); C8 (wz 3)]
  /\ rw_cells asegs m1 (bv_unsigned sp + -48) [C8 s4v; C8 s3v; C8 s2v; C8 s1v; C8 s0v; C8 rav]
  /\ rw_cells asegs m1 I [C8 (wz itv)]
  /\ rw_cells asegs m1 E [CB 16 (le8 (wz e) ++ le8 (wz AG_HTTP_CAT)); C8 (wz (ec_flags E0))]
  /\ stk asegs m1 lo (bv_unsigned sp + -80)
  /\ bytes_at asegs m1 it0 bs
  /\ munch (chx_W lo sp I E) m m1 /\ wmono asegs m m1 /\ mem_inv asegs m1
  /\ AHttpCat m1 true /\ chx_side m it0 E lo shi (Z.of_nat (length bs)).

