Lemma chx_tail : forall rax ra sp gp tp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s3x s4x s0v s1v s2v s3v s4v s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (it0 I E lo shi : Z) (bs : list byte) (itv : Z) (E0 : ecv)
    (j8 : list byte) (e loc : Z),
  chx_tctx m m1 sp s0v s1v s2v s3v s4v ra it0 I E lo shi bs itv E0 j8 e ->
  chx_pure sp it0 I E lo shi bs E0 ->
  (e = HE_NEED_MORE \/ e = HE_BAD_CHUNK_EXTENSION) -> 4 <= loc -> loc + 1 < 2^64 -> Z.odd (loc + 1) = true ->
  it0 <= itv <= it0 + Z.of_nat (length bs) ->
