(* [comment removed for export] *)
Definition chx_exitB_stmt (pc e : Z) : Prop :=
  forall rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s1x s2x s3x s4x s0v s1v s2v s3v s4v s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (it0 I E lo shi : Z) (bs : list byte) (itv : Z) (E0 : ecv) (g : bool) (j8 junk : list byte),
  chx_ctx m m1 sp s0v s1v s2v s3v s4v ra it0 I E lo shi bs itv E0 g j8 junk -> chx_pure sp it0 I E lo shi bs E0 ->
  it0 <= itv <= it0 + Z.of_nat (length bs) ->
  evt asegs (chx_post ra sp gp tp s0v s1v s2v s3v s4v s5 s6 s7 s8 s9 s10 s11 F fc it0 I E lo shi bs E0 m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -80)) gp tp t0 t1 t2 (wz E) s1x a0 a1 a2 a3 a4 a5 a6 a7
              s2x s3x s4x s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None m1 (seg_rom asegs)).

Local Ltac chx_exitB_tac e PRE :=
  unfold chx_exitB_stmt;
  intros rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s1x s2x s3x s4x s0v s1v s2v s3v s4v s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    F fc m m1 it0 I E lo shi bs itv E0 g j8 junk;
  intros CTX PURE ITV;
  destruct CTX as (FR0 & TMP & FRhi & IT & EC & ST & WIN & MU & WM & MI & MU2 & HC & SIDE);
  pose proof PURE as PURE';
  destruct PURE' as (EOK & LO & CEIL & APP & QHI & ILO & IHI & IAL & APE & EAL & DQE & SPAL & SHI);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  pose proof (aapp_bounds _ 24 APE ltac:(lia)) as (EB1 & EB2 & EB3 & EB4 & EB5);
  pose proof (aapp_bounds _ _ APP ltac:(lia)) as (PB1 & PB2 & PB3 & PB4 & PB5);
  pose proof aceil_facts as (AF1 & AF2 & AF3);
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  clear IAL APP SPAL AF2 AF3 EB5 PB5 EOK; hydeL DQE; hydeL EAL;
  unfold chx_W, CHX_STACK, AASSIGN_STACK, AINTRIN_STACK, AG_HTTP_CAT, AAPP_HI, AIMG_TOP in *;
  unfold wz;
  (* [comment removed for export] *)
  PRE; step; step; step; step; step; step; step;
  join_frameA TMP FRhi (bv_unsigned sp + -72); join_frameA FR0 TMP (bv_unsigned sp + -80);
  (* [comment removed for export] *)
  step; release_frame FR0 ST (bv_unsigned sp); step;
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
    let HC1 := fresh "HC1" in let AC1 := fresh "AC1" in let SK1 := fresh "SK1" in let XS1 := fresh "XS1" in let AE1 := fresh "AE1" in
    let junkE := fresh "junkE" in let EC' := fresh "EC'" in
    pose proof (chx_cat_now _ _ _ _ _ _ HC MU2 WM CEIL ILO ltac:(lia)) as HC1;
    clear MU2 HC;
    destruct (chx_side_now m mc sp it0 I E lo shi bs E0 SIDE ltac:(unfold chx_W, AG_HTTP_CAT; exact MU) WM PURE) as (AC1 & SK1 & XS1 & _ & AE1 & _);
    destruct (rw_cells_forget _ _ _ _ EC) as [junkE EC']; cbn [cells_size csize Nat.add ErrCodeCells] in EC'; clear EC;
    let AS := fresh "AS" in
    pose proof ASSIGNB as AS;
    unfold X8_assign.aassignB_stmt, aassign_post, aassign_W, P_A_EC_ASSIGN_HTTP, AG_HTTP_CAT, AASSIGN_STACK, AINTRIN_STACK in AS;
    callZc (AS _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ E e lo shi g junkE) (clear EC' ST AS);
    [ exact EC' | exact HC1 | exact XS1 | exact ST | lia | lia | exact APE | unhideL; exact EAL | lia
    | exact MI | exact AC1 | exact SK1 | exact AE1 | ]
  end;
  lazymatch goal with XS' : AXStatics ?mx, HC' : AHttpCat ?mx true |- _ =>
    chx_finish itv (EC_http e) true;
    right; unfold EC_http, ec_make, ec_ok, HE_NEED_MORE, HE_BAD_CHUNK_EXTENSION, AG_HTTP_CAT;
    cbn [ec_val ec_cat ec_flags Z.eqb]; repeat split; try lia; reflexivity
